pub fn plugin_command_to_json(v: &PluginCommand) -> Result<Value, WireError> {
    match v {
        PluginCommand::AddPart(x) => variant_to("add-part", part_draft_to_json(x)),
        PluginCommand::AddFeature(x) => variant_to("add-feature", add_feature_to_json(x)),
        PluginCommand::AddComponent(x) => variant_to("add-component", component_change_to_json(x)),
        PluginCommand::EditComponent(x) => {
            variant_to("edit-component", component_change_to_json(x))
        }
        PluginCommand::AddJoint(x) => variant_to("add-joint", joint_change_to_json(x)),
        PluginCommand::EditJoint(x) => variant_to("edit-joint", joint_change_to_json(x)),
        PluginCommand::AddMaterial(x) => variant_to("add-material", material_draft_to_json(x)),
        PluginCommand::AssignMaterial(x) => {
            variant_to("assign-material", assign_material_to_json(x))
        }
    }
}

pub fn plugin_command_from_json(v: &Value) -> Result<PluginCommand, WireError> {
    let (case, payload) = variant(v)?;
    match case {
        "add-part" => {
            variant_payload("add-part", part_draft_from_json(payload)).map(PluginCommand::AddPart)
        }
        "add-feature" => variant_payload("add-feature", add_feature_from_json(payload))
            .map(PluginCommand::AddFeature),
        "add-component" => variant_payload("add-component", component_change_from_json(payload))
            .map(PluginCommand::AddComponent),
        "edit-component" => variant_payload("edit-component", component_change_from_json(payload))
            .map(PluginCommand::EditComponent),
        "add-joint" => variant_payload("add-joint", joint_change_from_json(payload))
            .map(PluginCommand::AddJoint),
        "edit-joint" => variant_payload("edit-joint", joint_change_from_json(payload))
            .map(PluginCommand::EditJoint),
        "add-material" => variant_payload("add-material", material_draft_from_json(payload))
            .map(PluginCommand::AddMaterial),
        "assign-material" => variant_payload("assign-material", assign_material_from_json(payload))
            .map(PluginCommand::AssignMaterial),
        other => Err(unknown_case(
            "plugin-command",
            other,
            &[
                "add-part",
                "add-feature",
                "add-component",
                "edit-component",
                "add-joint",
                "edit-joint",
                "add-material",
                "assign-material",
            ],
        )),
    }
}

